const trashDays=30, trashMillis=trashDays*86400000;
let trashEntries=[];
async function moveToTrash(cid,type,id,record){
 if(!me||!cid||!['jobs','egenkontroller'].includes(type))throw Error('Ogiltig radering');
 const batch=writeBatch(db);
 const original=doc(db,'companies',cid,type,id);
 const data={...record};delete data.id;
 batch.set(trashRef(cid,type,id),{companyId:cid,recordType:type,originalId:id,payload:data,deletedBy:me.uid,deletedByName:profile?.name||me.email||'',deletedAt:serverTimestamp(),expiresAt:new Date(Date.now()+trashMillis)});
 batch.delete(original);
 await batch.commit();
}
function trashDate(v){return v?.toDate?.()|| (v?.seconds?new Date(v.seconds*1000):null)}
function renderTrash(){
 const el=$('trashList');if(!el)return;
 if(!platformOwner()){el.innerHTML='';return}
 const now=Date.now();
 el.innerHTML=trashEntries.map(t=>{
  const expires=trashDate(t.expiresAt),remaining=expires?Math.max(0,Math.ceil((expires.getTime()-now)/86400000)):0;
  const company=companies.find(c=>c.id===t.companyId)?.name||t.companyId;
  const label=t.recordType==='jobs'?'Asfaltjobb':'Egenkontroll';
  const title=t.recordType==='jobs'?t.payload?.customer:(t.payload?.payload?.customer||t.payload?.payload?.project||'Egenkontroll');
  return `<article class="user"><div><h3>${esc(label)} – ${esc(title||'Utan namn')}</h3><div class="meta">${esc(company)} • Raderad ${esc(trashDate(t.deletedAt)?.toLocaleString('sv-SE')||'nyligen')} • Av ${esc(t.deletedByName||t.deletedBy||'Okänd')} • ${remaining} dagar kvar</div></div><div class="actions">${remaining>0?`<button type="button" class="smallbtn primary" data-trash-restore="${esc(t.id)}">Återställ</button>`:'<span class="meta">Återställningstiden har gått ut</span>'}</div></article>`
 }).join('')||'<p>Papperskorgen är tom.</p>';
}
function listenTrash(){if(!platformOwner())return;unsubs.push(onSnapshot(trashCollection(),snap=>{trashEntries=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>(b.deletedAt?.seconds||0)-(a.deletedAt?.seconds||0));renderTrash()},err=>toast('Papperskorg: '+err.message)))}
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-trash-restore]');if(!b||!platformOwner())return;
 const t=trashEntries.find(x=>x.id===b.dataset.trashRestore);if(!t)return;
 const expires=trashDate(t.expiresAt);if(!expires||expires.getTime()<=Date.now()){toast('30 dagar har passerat.');return}
 if(!confirm('Återställa '+(t.recordType==='jobs'?'asfaltjobbet':'egenkontrollen')+' till företaget?'))return;
 b.disabled=true;
 try{
  const target=doc(db,'companies',t.companyId,t.recordType,t.originalId);
  const batch=writeBatch(db);batch.set(target,t.payload);batch.delete(trashRef(t.companyId,t.recordType,t.originalId));await batch.commit();toast('Återställd!');
 }catch(err){toast('Kunde inte återställa: '+err.message)}finally{b.disabled=false}
});

