function listenCompanies(){listenTrash();unsubs.push(onSnapshot(collection(db,'companies'),snapshot=>{companies=snapshot.docs.map(d=>({id:d.id,...d.data()}));renderTrash();$('companiesList').innerHTML=companies.map(c=>`<article class="user"><div><h3>${esc(c.name)}</h3><div class="meta">Org.nr ${esc(c.orgNumber)} • ${esc(c.status)} • ${esc(c.plan||'start')} • ID: ${esc(c.id)}</div></div><div class="actions">${c.status==='pending'?`<button class="smallbtn primary" data-company="${esc(c.id)}" data-company-status="approved">Godkänn</button><button class="smallbtn secondary" data-company="${esc(c.id)}" data-company-status="rejected">Neka</button>`:c.status==='approved'?`<button class="smallbtn secondary" data-company="${esc(c.id)}" data-company-status="paused">Arkivera</button>`:`<button class="smallbtn primary" data-company="${esc(c.id)}" data-company-status="approved">Återaktivera</button>`}<button class="smallbtn secondary" data-company-delete="${esc(c.id)}" style="border-color:#b65b5b;color:#ffb6b6">Radera permanent</button><label>Plan <select data-company-plan="${esc(c.id)}"><option value="start" ${c.plan==='start'?'selected':''}>Start 299 kr</option><option value="pro" ${c.plan==='pro'?'selected':''}>Pro 699 kr</option><option value="enterprise" ${c.plan==='enterprise'?'selected':''}>Enterprise 1 499 kr</option></select></label><label><input type="checkbox" data-company-free="${esc(c.id)}" ${c.billingExempt?'checked':''}> Gratisundantag</label></div></article>`).join('')||'<p>Inga företag registrerade.</p>'},e=>toast('Företag: '+e.message)))}
